function check([barcodes], actual) {
  if (!Array.isArray(actual) || actual.length !== barcodes.length) return false;
  for (let i = 1; i < actual.length; i++) if (actual[i] === actual[i - 1]) return false;
  const want = [...barcodes].sort((a, b) => a - b), got = [...actual].sort((a, b) => a - b);
  return want.every((value, i) => value === got[i]);
}

