function validate([barcodes]) {
  if (!Array.isArray(barcodes) || barcodes.length < 1 || barcodes.length > 10000) return 'barcodes needs 1 to 10^4 values.';
  if (!barcodes.every(v => Number.isInteger(v) && v >= 1 && v <= 10000)) return 'Each barcode is an integer from 1 to 10^4.';
  const count = new Map();
  for (const v of barcodes) count.set(v, (count.get(v) ?? 0) + 1);
  if (Math.max(...count.values()) > Math.ceil(barcodes.length / 2)) return 'No valid order exists: one value occurs more than half the time.';
  return null;
}

