function rearrangeBarcodes(barcodes) {
  const count = new Map();
  for (const code of barcodes) {
    count.set(code, (count.get(code) ?? 0) + 1);
  }

  // A max-heap of [remaining, code] pairs, ordered by remaining.
  const heap = [];
  const higher = (a, b) => heap[a][0] > heap[b][0];
  const swap = (a, b) => {
    [heap[a], heap[b]] = [heap[b], heap[a]];
  };
  const push = item => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && higher(i, (i - 1) >> 1)) {
      swap(i, (i - 1) >> 1);
      i = (i - 1) >> 1;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let largest = i;
        for (const child of [2 * i + 1, 2 * i + 2]) {
          if (child < heap.length && higher(child, largest)) {
            largest = child;
          }
        }
        if (largest === i) {
          break;
        }
        swap(i, largest);
        i = largest;
      }
    }
    return top;
  };
  for (const [code, remaining] of count) {
    push([remaining, code]);
  }

  const result = [];
  let waiting = null;
  while (heap.length > 0) {
    const [remaining, code] = pop();
    result.push(code);
    if (waiting !== null) {
      push(waiting);
    }
    waiting = remaining > 1 ? [remaining - 1, code] : null;
  }
  return result;
}

