function rearrangeBarcodes(barcodes) {
  // Backtracking: try each value that still has copies and differs from the previous one.
  // A branch is cut once some value has more copies than half the remaining slots, rounded up.
  const count = new Map();
  for (const b of barcodes) count.set(b, (count.get(b) || 0) + 1);
  const values = [...count.keys()].sort((a, b) => a - b);
  const out = [];
  const place = () => {
    const left = barcodes.length - out.length;
    if (left === 0) return true;
    if (values.some(v => count.get(v) > Math.ceil(left / 2))) return false;
    for (const v of values) {
      if (count.get(v) === 0 || out[out.length - 1] === v) continue;
      count.set(v, count.get(v) - 1);
      out.push(v);
      if (place()) return true;
      out.pop();
      count.set(v, count.get(v) + 1);
    }
    return false;
  };
  place();
  return out;
}

