function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  const top = size === 'large' ? 10000 : 6;
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = int(0, i);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  for (;;) {
    const r = rand();
    let list;
    if (r < 0.35) {
      // One value takes the largest share allowed; the others are random.
      const main = int(1, top), share = Math.ceil(n / 2) - (rand() < 0.3 ? 1 : 0);
      list = Array.from({ length: n }, (_, i) => (i < share ? main : int(1, top)));
    } else if (r < 0.55) {
      // Only a few different values.
      const pool = Array.from({ length: int(2, 4) }, () => int(1, top));
      list = Array.from({ length: n }, () => pool[int(0, pool.length - 1)]);
    } else {
      const span = size === 'large' ? int(2, 10000) : int(1, top);
      list = Array.from({ length: n }, () => int(1, span));
    }
    const count = new Map();
    for (const v of list) count.set(v, (count.get(v) ?? 0) + 1);
    if (Math.max(...count.values()) <= Math.ceil(n / 2)) return [shuffle(list)];
  }
}
